-- Harden the exposed wrapper; privileged mutation lives in private schema.
create or replace function private.award_points(p_points integer,p_reason text,p_entity_type text default null,p_entity_id uuid default null) returns public.gamification_points language plpgsql security definer set search_path=public,pg_temp as $$ declare v_user uuid:=auth.uid(); v_points public.gamification_points%rowtype; begin if v_user is null then raise exception 'authentication_required'; end if; if p_points is null or p_points=0 or abs(p_points)>1000 then raise exception 'invalid_points'; end if; insert into public.gamification_points(user_id,total_points,level) values(v_user,greatest(p_points,0),greatest(1,floor(greatest(p_points,0)/100)+1)) on conflict(user_id) do update set total_points=greatest(0,public.gamification_points.total_points+p_points),level=greatest(1,floor(greatest(0,public.gamification_points.total_points+p_points)/100)+1),updated_at=now() returning * into v_points; insert into public.gamification_events(user_id,points,reason,entity_type,entity_id) values(v_user,p_points,p_reason,p_entity_type,p_entity_id); return v_points; end; $$;
revoke all on function private.award_points(integer,text,text,uuid) from public,anon,authenticated;drop function if exists public.award_points(integer,text,text,uuid);create or replace function public.award_points(p_points integer,p_reason text,p_entity_type text default null,p_entity_id uuid default null) returns public.gamification_points language sql security invoker set search_path=public,pg_temp as $$ select * from private.award_points(p_points,p_reason,p_entity_type,p_entity_id); $$;revoke all on function public.award_points(integer,text,text,uuid) from public,anon;grant execute on function public.award_points(integer,text,text,uuid) to authenticated;